package com.jobtrack.controller;
import com.jobtrack.service.UserService;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/profile") public class ProfileController {private final UserService users;public ProfileController(UserService u){users=u;}
 @GetMapping public String profile(Authentication a,Model m){m.addAttribute("user",users.byEmail(a.getName()));return "profile";}
 @PostMapping public String update(@RequestParam String fullName,Authentication a,RedirectAttributes r){if(fullName==null||fullName.isBlank()||fullName.length()>80){r.addFlashAttribute("error","Enter a name between 1 and 80 characters.");return "redirect:/profile";}users.updateProfile(a.getName(),fullName);r.addFlashAttribute("success","Profile updated successfully.");return "redirect:/profile";}
 @PostMapping("/password") public String password(@RequestParam String currentPassword,@RequestParam String newPassword,@RequestParam String confirmPassword,Authentication a,RedirectAttributes r){if(newPassword.length()<8||newPassword.length()>72||!newPassword.equals(confirmPassword)){r.addFlashAttribute("error","New passwords must match and contain 8–72 characters.");return "redirect:/profile";}try{users.changePassword(a.getName(),currentPassword,newPassword);r.addFlashAttribute("success","Password changed successfully.");}catch(IllegalArgumentException e){r.addFlashAttribute("error",e.getMessage());}return "redirect:/profile";}
}
